import * as THREE from './assets/three.module.js';
import {projects,contact} from './portfolio.js';
import {createDriver} from './drive.js';
import {GameAudio} from './audio.js';
const gameAudio=new GameAudio();
const $=id=>document.getElementById(id),canvas=$('world'),panel=$('panel');
let started=false,inCar=false,selected=0,near=null,activePanel=null,driver;
let carSpeed=0,heading=-Math.PI/2,closeCar=false;
const keys=new Set(),stick={x:0,y:0},position=new THREE.Vector3(-2,0,-1);
let visited;
try{visited=JSON.parse(localStorage.getItem('felipe-mission-v1')||'[]').filter(x=>projects.some(p=>p.id===x));}catch{visited=[];}
let toastTimer,lastUI=0;
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function begin(){gameAudio.start().then(syncAudioUI).catch(()=>toast('Use o botão Som para ativar o áudio.'));started=true;$('intro').hidden=true;$('game-hud').hidden=false;document.body.classList.add('playing');if(!visited.includes(projects[selected].id))selectMission(selected);else{const n=projects.findIndex(p=>!visited.includes(p.id));if(n>=0)selectMission(n);}canvas.focus({preventScroll:true});toast('CJ na área · F para entrar no Infernus · E para abrir missões');}
function selectMission(index){selected=index;const p=projects[index];$('mission-title').textContent=p.mission;$('mission-description').textContent=p.objective;$('mission-tag').textContent=p.tag;$('mission-fraction').textContent=`${String(index+1).padStart(2,'0')} / 03`;$('mission-progress-bar').style.width=`${visited.length/3*100}%`;}
function closePanel(){panel.close();activePanel=null;document.body.classList.remove('paused');keys.clear();if(started)canvas.focus({preventScroll:true});}
function showPanel(label,html,type){activePanel=type;keys.clear();stick.x=stick.y=0;$('joystick-knob').style.transform='';$('panel-label').textContent=label;$('panel-content').innerHTML=html;if(!panel.open)panel.showModal();document.body.classList.add('paused');panel.scrollTop=0;}
function showProject(index,fromMarker=false){const p=projects[index];showPanel('ARQUIVO DE MISSÃO / '+String(index+1).padStart(2,'0'),`<article class="panel-body"><p class="panel-kicker">${p.tag}</p><h2>${p.name}</h2><p class="panel-summary">${p.summary}</p><img class="project-shot" src="./assets/${p.image}" alt="Página inicial do projeto ${p.name}"><div class="stack">${p.stack.map(x=>`<span>${x}</span>`).join('')}</div><h3>O que eu construí</h3><p class="panel-summary">${p.role}.</p><ul class="proof">${p.proof.map(x=>`<li>${x}</li>`).join('')}</ul><div class="project-links"><a class="secondary" href="${p.live}" target="_blank" rel="noopener noreferrer">Visitar projeto</a><a class="secondary" href="${p.repo}" target="_blank" rel="noopener noreferrer">Ver estudo de caso</a></div><button class="primary project-complete" id="project-action">${fromMarker?'Concluir missão':visited.includes(p.id)?'Revisitar no mapa':'Marcar no mapa'}</button><p class="panel-note">Projeto real do meu portfólio. A cidade e a missão são uma forma interativa de conhecer o trabalho.</p></article>`,'project');$('project-action').onclick=()=>{if(fromMarker)completeMission(index);else{selectMission(index);closePanel();if(!started)begin();toast('Destino marcado: '+p.name);}};}
function completeMission(index){const p=projects[index];if(!visited.includes(p.id))visited.push(p.id);try{localStorage.setItem('felipe-mission-v1',JSON.stringify(visited));}catch{}closePanel();playChime();$('mission-progress-bar').style.width=`${visited.length/3*100}%`;if(visited.length===3){$('completion').hidden=false;keys.clear();}else{toast('Missão cumprida · '+p.name);selectMission(projects.findIndex(p=>!visited.includes(p.id)));}}
function showProjects(){showPanel('PORTFÓLIO / PROJETOS REAIS',`<section class="panel-body"><p class="panel-kicker">DO PROBLEMA À PRODUÇÃO</p><h2>Escolha sua<br>próxima missão.</h2><p class="panel-summary">Pagamentos, apps e IA aplicada. Três projetos para conhecer meu jeito de construir software.</p>${projects.map((p,i)=>`<button class="project-list-item" data-project="${i}"><img src="./assets/${p.image}" alt=""><span><strong>${p.name}</strong><small>${p.tag}</small></span><span class="project-status">${visited.includes(p.id)?'✓':'◇'}</span></button>`).join('')}<a class="secondary" style="margin-top:28px" href="${contact.portfolio}" target="_blank" rel="noopener noreferrer">Ver portfólio completo</a><p class="panel-note">Você pode conhecer todos os projetos sem jogar. No modo missão, encontre os marcadores para concluir os objetivos.</p></section>`,'projects');document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>showProject(Number(b.dataset.project)));}
function showAbout(){showPanel('SOBRE O DESENVOLVEDOR',`<section class="panel-body"><p class="panel-kicker">BELÉM, PARÁ · BRASIL</p><h2>Felipe Souza.</h2><p class="about-role">Engenheiro de software full stack.</p><p class="panel-summary">Construo plataformas SaaS, sistemas de pagamentos, bilheteria, IA aplicada e apps iOS. Do banco de dados ao deploy, com atenção às regras que precisam continuar certas quando o sistema encontra o mundo real.</p><h3>O caminho que eu percorro</h3><ul class="proof"><li>Entender a operação e o problema de quem usa.</li><li>Modelar dados, responsabilidades e regras de negócio.</li><li>Construir backend, interfaces, integrações e apps.</li><li>Testar concorrência, erros e os casos fora do caminho feliz.</li><li>Publicar, acompanhar e melhorar em produção.</li></ul><div class="stack"><span>Backend & APIs</span><span>React</span><span>SwiftUI</span><span>Pagamentos</span><span>IA aplicada</span><span>Infraestrutura</span></div><a class="secondary" href="${contact.github}" target="_blank" rel="noopener noreferrer">Conhecer meu GitHub</a></section>`,'about');}
function showContact(){showPanel('A PRÓXIMA MISSÃO É NOSSA',`<section class="panel-body"><p class="panel-kicker">VAMOS CONSTRUIR ALGO</p><h2>Seu projeto.<br>Nosso próximo<br>ponto no mapa.</h2><p class="panel-summary">Estou aberto a oportunidades em engenharia de software e a projetos com começo, meio e produção. Me conte o problema que você quer resolver.</p><a class="contact-card" href="mailto:${contact.email}?subject=Vamos%20conversar%20sobre%20um%20projeto"><span>E-MAIL</span><strong>${contact.email}</strong></a><a class="contact-card" href="${contact.github}" target="_blank" rel="noopener noreferrer"><span>GITHUB</span><strong>github.com/filpe19</strong></a><a class="contact-card" href="${contact.portfolio}" target="_blank" rel="noopener noreferrer"><span>PORTFÓLIO COMPLETO</span><strong>felipesouza.dev</strong></a></section>`,'contact');}
function showHelp(){showPanel('GUIA DO VISITANTE',`<section class="panel-body"><p class="panel-kicker">SEU BRIEFING</p><h2>Grove Street.<br>Seu ponto de partida.</h2><p class="panel-summary">Explore a Grove Street com CJ, entre no Infernus e siga os marcadores luminosos, conheça cada projeto e conclua as três missões. Nenhum projeto fica escondido: use o botão Projetos para ir direto ao conteúdo.</p><div class="help-grid"><kbd>W A S D</kbd><span>Andar a pé; acelerar, dar ré e virar no carro. As setas também funcionam.</span><kbd>Shift</kbd><span>Correr com CJ.</span><kbd>F</kbd><span>Entrar ou sair do Infernus. Pare o carro antes de sair.</span><kbd>C</kbd><span>Alternar câmera de perseguição e vista de cima.</span><kbd>E</kbd><span>Abrir a missão quando estiver perto do marcador.</span><kbd>Espaço</kbd><span>Frear o carro.</span><kbd>M</kbd><span>Abrir o mapa e escolher um destino.</span><kbd>P</kbd><span>Abrir todos os projetos.</span><kbd>Esc</kbd><span>Fechar um painel.</span></div><p class="panel-note">No celular, use o controle circular para se mover e o botão E para interagir. O progresso das missões é salvo apenas neste navegador.</p><button class="secondary" id="restart-progress">Recomeçar as missões</button></section>`,'help');$('restart-progress').onclick=()=>{visited=[];try{localStorage.removeItem('felipe-mission-v1');}catch{}selectMission(0);closePanel();resetPosition();toast('Um novo começo. As três missões estão disponíveis.');};}
function showMap(){showPanel('MAPA / SUA ROTA PELA CIDADE',`<section class="panel-body"><p class="panel-kicker">ESCOLHA SEU DESTINO</p><h2>Todo caminho<br>leva a um projeto.</h2><canvas id="full-map" width="600" height="520" class="map-full" aria-label="Mapa completo da cidade"></canvas>${projects.map((p,i)=>`<button class="map-stop" data-destination="${i}"><span>${visited.includes(p.id)?'✓':'◇'}</span><div>${p.name}<small>${p.district}</small></div></button>`).join('')}<button class="secondary" id="map-reset" style="margin-top:24px">Voltar à Grove Street</button></section>`,'map');drawMap($('full-map'),true);document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{selectMission(Number(b.dataset.destination));closePanel();if(!started)begin();toast('Destino marcado no minimapa.');});$('map-reset').onclick=()=>{resetPosition();closePanel();};}

function resetPosition(){carSpeed=0;keys.clear();stick.x=stick.y=0;driver?.reset();toast('De volta à Grove Street.');}
function interact(){if(!started||panel.open||!$('completion').hidden)return;if(near!==null){carSpeed=0;showProject(near,true);}else if(inCar||closeCar)driver?.toggleVehicle();else toast('Siga o marcador no mapa para encontrar sua missão.');}
function vehicleAction(){if(started&&!panel.open&&$('completion').hidden)driver?.toggleVehicle();}
function drawMap(target,full=false){
  if(!target||!driver)return;
  const c=target.getContext('2d'),w=target.width,h=target.height,scale=full?1.6:1.35,center=full?{x:-70,z:0}:position;
  c.fillStyle='#99b192';c.fillRect(0,0,w,h);c.save();c.translate(w/2,h/2);
  const xx=x=>(x-center.x)*scale,zz=z=>(z-center.z)*scale;
  for(const [index,img] of driver.radar){const col=index%12,row=Math.floor(index/12),x=-3000+col*500-2490,z=-(3000-row*500+1670);c.drawImage(img,xx(x),zz(z),500*scale,500*scale);}
  c.fillStyle='#12231830';c.fillRect(-w/2,-h/2,w,h);
  const p=projects[selected];c.setLineDash([3,5]);c.strokeStyle='#fff';c.lineWidth=1.7;c.beginPath();c.moveTo(xx(position.x),zz(position.z));c.lineTo(xx(p.x),zz(p.z));c.stroke();c.setLineDash([]);
  projects.forEach((p,i)=>{c.save();c.translate(xx(p.x),zz(p.z));c.rotate(Math.PI/4);c.fillStyle=visited.includes(p.id)?'#e9eadb':i===selected?'#eaff70':'#f0be80';c.strokeStyle='#19291d';c.lineWidth=2;c.fillRect(-5,-5,10,10);c.strokeRect(-5,-5,10,10);c.restore();if(full){c.textAlign='center';c.font='600 14px Arial';c.lineWidth=4;c.strokeStyle='#16251b';c.strokeText(p.name,xx(p.x),zz(p.z)+25);c.fillStyle='#fff';c.fillText(p.name,xx(p.x),zz(p.z)+25);}});
  c.save();c.translate(xx(position.x),zz(position.z));c.rotate(heading);c.fillStyle='#fff';c.strokeStyle='#20322c';c.lineWidth=2;c.beginPath();c.moveTo(0,-8);c.lineTo(6,6);c.lineTo(0,3);c.lineTo(-6,6);c.closePath();c.fill();c.stroke();c.restore();c.restore();c.fillStyle='#fff';c.font='700 12px Arial';c.textAlign='center';c.fillText('N',w/2,16);
}
function updateFrame(frame){
  position.copy(frame.position);carSpeed=frame.speed;heading=frame.heading;inCar=frame.inCar;closeCar=frame.closeCar;gameAudio.update(frame);
  if(frame.time-lastUI>.1){
    lastUI=frame.time;near=null;let nearest=7;
    projects.forEach((p,i)=>{const d=Math.hypot(position.x-p.x,position.z-p.z);if(d<nearest){nearest=d;near=i;}});
    $('distance').textContent=Math.round(Math.hypot(position.x-projects[selected].x,position.z-projects[selected].z))+' m';
    $('speed').innerHTML=Math.round(Math.abs(carSpeed)*3.6)+'<small>KM/H</small>';
    $('vehicle-label').textContent=inCar?'CJ · INFERNUS':'CJ · A PÉ';$('touch-run').textContent=inCar?'FREAR':'CORRER';$('touch-run').setAttribute('aria-label',inCar?'Frear':'Correr');$('vehicle-button').textContent=inCar?'SAIR':'CARRO';$('vehicle-button').setAttribute('aria-label',inCar?'Sair do carro':'Entrar no carro');$('district-name').textContent=position.x< -90?'GANTON':'GROVE STREET';
    $('interaction').hidden=!started||panel.open||(near===null&&!closeCar&&!inCar)||!$('completion').hidden;
    $('interaction').querySelector('span').textContent=near!==null?'Conhecer '+projects[near].name:inCar?'Sair do Infernus':'Entrar no Infernus';
    drawMap($('radar'));if(activePanel==='map')drawMap($('full-map'),true);
  }
  syncAudioUI();
}
function playChime(){gameAudio.chime();}
function syncAudioUI(){const on=gameAudio.settings.enabled&&!!gameAudio.context;$('sound-label').textContent=on?'SOM ON':'SOM OFF';$('sound-button').setAttribute('aria-pressed',String(on));$('sound-button').setAttribute('aria-label',on?'Desativar som':'Ativar som');$('radio-button').setAttribute('aria-label','Rádio e volumes: '+gameAudio.stations[gameAudio.settings.station].name);}
async function toggleSound(){if(!gameAudio.context){gameAudio.settings.enabled=true;await gameAudio.start();}else{gameAudio.toggle();if(gameAudio.settings.enabled)await gameAudio.start();}syncAudioUI();}
function showAudio(){
  const settings=gameAudio.settings,station=gameAudio.stations[settings.station];
  showPanel('RÁDIO / MIXER DE ÁUDIO',`<section class="panel-body"><p class="panel-kicker">SINTONIZE SEU PASSEIO</p><h2>${station.name}</h2><p class="panel-summary">${station.track}</p><div class="radio-stations">${gameAudio.stations.map((s,i)=>`<button class="secondary" data-station="${i}" aria-pressed="${settings.station===i}">${s.name}<small>${s.bpm} BPM</small></button>`).join('')}</div><div class="audio-slider"><label for="effects-volume">Motor, passos e efeitos <output id="effects-value">${Math.round(settings.effects*100)}%</output></label><input id="effects-volume" type="range" min="0" max="100" value="${Math.round(settings.effects*100)}"></div><div class="audio-slider"><label for="music-volume">Música da rádio <output id="music-value">${Math.round(settings.music*100)}%</output></label><input id="music-volume" type="range" min="0" max="100" value="${Math.round(settings.music*100)}"></div><button class="secondary" id="audio-master">${settings.enabled?'Silenciar tudo':'Ativar som'}</button><p class="panel-note">O som começa quando você inicia a missão. Suas preferências de rádio e volume ficam salvas neste navegador.</p></section>`,'audio');
  document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>{gameAudio.setStation(Number(b.dataset.station));showAudio();});
  for(const type of ['effects','music'])$(type+'-volume').oninput=e=>{gameAudio.setVolume(type,Number(e.target.value)/100);$(type+'-value').textContent=e.target.value+'%';};
  $('audio-master').onclick=async()=>{await toggleSound();showAudio();};
}

function hookControls(){
  $('start-button').onclick=begin;$('projects-button').onclick=showProjects;$('skip-button').onclick=showProjects;$('fallback-projects').onclick=showProjects;$('about-button').onclick=showAbout;$('contact-button').onclick=showContact;$('close-panel').onclick=closePanel;$('help-button').onclick=showHelp;$('map-button').onclick=showMap;$('reset-button').onclick=resetPosition;$('interaction').onclick=interact;$('touch-action').onclick=interact;$('sound-button').onclick=()=>toggleSound().catch(()=>toast('O som não está disponível neste navegador.'));$('radio-button').onclick=showAudio;$('vehicle-button').onclick=vehicleAction;
  $('home-link').onclick=e=>{e.preventDefault();if(panel.open)closePanel();started=false;keys.clear();$('intro').hidden=false;$('game-hud').hidden=true;document.body.classList.remove('playing');};$('completion-contact').onclick=()=>{$('completion').hidden=true;showContact();};$('keep-exploring').onclick=()=>{$('completion').hidden=true;toast('A cidade continua aberta. Explore à vontade.');};
  panel.addEventListener('cancel',()=>{activePanel=null;keys.clear();document.body.classList.remove('paused');});panel.addEventListener('click',e=>{if(e.target===panel&&e.clientX<panel.getBoundingClientRect().left)closePanel();});
  addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(panel.open||e.target.matches('input,textarea'))return;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(!e.repeat){if(key==='e')interact();if(key==='f')vehicleAction();if(key==='c')driver?.toggleCamera();if(key==='r')resetPosition();if(key==='p')showProjects();if(key==='m'&&started)showMap();}keys.add(key);});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();stick.x=stick.y=0;});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();stick.x=stick.y=0;}});
  const joystick=$('joystick');let pointer=null;function updateStick(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),limit=32;stick.x=dx/Math.max(len,limit);stick.y=dy/Math.max(len,limit);$('joystick-knob').style.transform=`translate(${stick.x*limit}px,${stick.y*limit}px)`;}
  joystick.onpointerdown=e=>{pointer=e.pointerId;joystick.setPointerCapture(pointer);updateStick(e);};joystick.onpointermove=e=>{if(e.pointerId===pointer)updateStick(e);};const release=e=>{if(e.pointerId===pointer){pointer=null;stick.x=stick.y=0;$('joystick-knob').style.transform='';}};joystick.onpointerup=release;joystick.onpointercancel=release;$('touch-run').onpointerdown=e=>{keys.add('shift');e.currentTarget.setPointerCapture(e.pointerId);};$('touch-run').onpointerup=$('touch-run').onpointercancel=()=>keys.delete('shift');
}
hookControls();
$('start-button').disabled=true;
try{
  driver=await createDriver(canvas,{keys,stick,message:toast,vehicle:enter=>gameAudio.vehicle(enter),step:()=>gameAudio.step(),bump:()=>gameAudio.impact(),state:()=>({started,selected,paused:panel.open||!$('completion').hidden||document.hidden}),progress:(n,total)=>{$('loading').querySelector('p').textContent='Carregando Grove Street · '+Math.round(n/total*100)+'%';},frame:updateFrame});
  selectMission(0);$('loading').hidden=true;$('start-button').disabled=false;
}catch(error){console.error('3D indisponível:',error);$('loading').hidden=true;$('intro').hidden=true;$('fallback').hidden=false;}
